import {pct,signed,fmt,slugify,raceLabel,winSide,winProbability,uncertaintyScore,runScenario,filterRaces,searchRecords,scoreSearch,buildElectionSummary} from '/core.mjs';

let MODEL=null,STATUS=null,SOURCES=null,HISTORY_INDEX=null,SEARCH=[],FULL_MODEL_PROMISE=null;
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const dateFmt=v=>{if(!v)return 'Unavailable';const d=new Date(v);return Number.isNaN(d.valueOf())?esc(v):d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})};
const dayFmt=v=>{if(!v)return 'Unavailable';const d=new Date(`${v}T12:00:00Z`);return Number.isNaN(d.valueOf())?esc(v):d.toLocaleDateString(undefined,{dateStyle:'medium'})};
const ageDays=v=>v?Math.floor((Date.now()-new Date(v).valueOf())/86400000):null;
const stateName=code=>({AL:'Alabama',AK:'Alaska',AZ:'Arizona',AR:'Arkansas',CA:'California',CO:'Colorado',CT:'Connecticut',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',ID:'Idaho',IL:'Illinois',IN:'Indiana',IA:'Iowa',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',ME:'Maine',MD:'Maryland',MA:'Massachusetts',MI:'Michigan',MN:'Minnesota',MS:'Mississippi',MO:'Missouri',MT:'Montana',NE:'Nebraska',NV:'Nevada',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NY:'New York',NC:'North Carolina',ND:'North Dakota',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VT:'Vermont',VA:'Virginia',WA:'Washington',WV:'West Virginia',WI:'Wisconsin',WY:'Wyoming',DC:'District of Columbia'})[code]||code;

function routeFromLocation(){
  if(window.__MIDTERM_ROUTE__)return window.__MIDTERM_ROUTE__;
  const path=location.pathname.split('/').filter(Boolean);
  if(path[0]==='races'&&path[1])return {view:'race',id:decodeURIComponent(path[1])};
  if(path[0]==='candidates'&&path[1])return {view:'candidate',id:decodeURIComponent(path[1])};
  if(path[0]==='pollsters'&&path[1])return {view:'pollster',id:decodeURIComponent(path[1])};
  const p=new URLSearchParams(location.search);
  if(p.get('race'))return {view:'race',id:p.get('race')};
  if(p.get('candidate'))return {view:'candidate',id:p.get('candidate')};
  if(p.get('pollster'))return {view:'pollster',id:p.get('pollster')};
  return {view:p.get('view')||'home'};
}
function urlFor(route,extra={}){
  const p=new URLSearchParams(extra);
  if(route.view==='race')return `/?race=${encodeURIComponent(route.id)}`;
  if(route.view==='candidate')return `/?candidate=${encodeURIComponent(route.id)}`;
  if(route.view==='pollster')return `/?pollster=${encodeURIComponent(route.id)}`;
  p.set('view',route.view||'home'); return `/?${p}`;
}
function navigate(route,extra={}){history.pushState(route,'',urlFor(route,extra));renderRoute(route);$('#primaryNav').classList.remove('open');$('#navToggle').setAttribute('aria-expanded','false');$('#content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'})}
window.addEventListener('popstate',()=>renderRoute(routeFromLocation()));
document.addEventListener('click',e=>{const a=e.target.closest('[data-route]');if(!a)return;e.preventDefault();navigate({view:a.dataset.route})});

function activeNav(view){const root=['race','candidate','pollster'].includes(view)?({race:'races',candidate:'candidates',pollster:'polls'}[view]):view;$$('#primaryNav a').forEach(a=>a.toggleAttribute('aria-current',a.dataset.route===root))}
function pageHead(kicker,title,deck,meta=''){return `<header class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1><p>${deck}</p></div>${meta?`<div class="page-meta">${meta}</div>`:''}</header>`}
function metaRow(label,value){return `<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`}
function partyProbBlock(ch,label){return `<article class="chamber-card"><div class="eyebrow">${label}</div><h2>${label==='HOUSE'?'218 seats for control':'51 Democratic seats for control'}</h2><div class="control-display"><div><small>DEMOCRATIC CONTROL</small><strong class="party-d">${pct(ch.dem_control_probability)}</strong></div><div class="slash">/</div><div><small>REPUBLICAN CONTROL</small><strong class="party-r">${pct(ch.rep_control_probability)}</strong></div></div><div class="seat-track" role="img" aria-label="Expected Democratic seat share"><span style="width:${(ch.expected_dem_seats/(label==='HOUSE'?435:100))*100}%"></span></div><div class="metric-line"><div class="metric"><b>${fmt(ch.expected_dem_seats,1)}</b><small>expected D seats</small></div><div class="metric"><b>${ch.median_dem_seats??'—'}</b><small>median D seats</small></div><div class="metric"><b>${(ch.dem_seats_80_interval||[]).join('–')||'—'}</b><small>80% interval</small></div><div class="metric"><b>${signed(ch.net_change_dem??NaN,1)}</b><small>projected net change</small></div></div></article>`}
function raceLink(r,content){return `<button type="button" data-open-race="${esc(r.race_code)}">${content}</button>`}
function raceMini(r){const side=winSide(r),p=winProbability(r);return `<div class="race-mini"><div class="race-code">${esc(r.race_code)}</div><div>${raceLink(r,`<strong>${esc(r.dem_candidate||'No D nominee')} <span class="muted">vs</span> ${esc(r.rep_candidate||'No R nominee')}</strong><small>${esc(r.rating||'Unrated')} · ${signed(r.forecast_margin_d_minus_r)}</small>`)}</div><div class="prob ${side==='D'?'lead-d':'lead-r'}">${pct(p)}<small>${side} WIN</small></div></div>`}
function empty(text){return `<div class="empty-state">${text}</div>`}
function sourceState(s){const state=s?.state||s?.health||'unavailable';return `<span class="source-state ${esc(state)}">${esc(state.toUpperCase())}</span>`}
function intervalText(ch,p=80){return (ch?.[`dem_seats_${p}_interval`]||[]).join('–')||'—'}

function distributionChart(ch,total,label){
  const dist=ch?.distribution||[]; if(!dist.length)return empty(`Seat distribution is unavailable in this snapshot. The next v1 production refresh will populate the full ${label} distribution.`);
  const max=Math.max(...dist.map(d=>d.probability),.001); const threshold=label==='House'?218:51;
  const bars=dist.map(d=>`<span class="bar ${d.seats>=threshold?'threshold':''}" style="height:${Math.max(2,d.probability/max*100)}%" title="${d.seats} D seats: ${pct(d.probability,1)}"></span>`).join('');
  return `<div class="distribution-wrap"><div class="distribution" role="img" aria-label="${label} Democratic seat probability distribution. Expected ${fmt(ch.expected_dem_seats,1)} seats; 80 percent interval ${intervalText(ch,80)}.">${bars}</div><div class="distribution-axis"><span>${dist[0]?.seats??''} D seats</span><span>control threshold ${threshold}</span><span>${dist.at(-1)?.seats??''} D seats</span></div><p class="chart-summary">Expected ${fmt(ch.expected_dem_seats,1)} Democratic seats · median ${ch.median_dem_seats??'—'} · 50% ${intervalText(ch,50)} · 80% ${intervalText(ch,80)} · 95% ${intervalText(ch,95)}.</p></div>`
}
function deltaText(v,unit='pp'){if(!Number.isFinite(v))return 'Unavailable';const sign=v>0?'+':'';return `${sign}${(v*(unit==='pp'?100:1)).toFixed(1)}${unit==='pp'?' pp':''}`}

function renderHome(){
  const h=MODEL.summary.house,s=MODEL.summary.senate,j=MODEL.summary.joint_control||{};
  const changes=MODEL.change_summary||{};
  const read=MODEL.briefing?.thirty_second_read||`The model currently gives Democrats ${pct(h.dem_control_probability)} probability of House control and ${pct(s.dem_control_probability)} probability of Senate control. The generic congressional ballot input is ${signed(MODEL.national_environment?.generic_ballot_d_minus_r)}.`;
  const movers=[...(MODEL.races||[])].sort((a,b)=>Math.abs(b.change?.dem_probability||0)-Math.abs(a.change?.dem_probability||0)).slice(0,6);
  const uncertain=[...(MODEL.races||[])].sort((a,b)=>uncertaintyScore(b)-uncertaintyScore(a)).slice(0,8);
  const source=MODEL.source_health||SOURCES?.sources||[]; const current=source.filter(x=>(x.state||x.health)==='current').length;
  $('#content').innerHTML=`
  <section class="hero"><div class="hero-grid"><div><div class="eyebrow">2026 US MIDTERM ELECTIONS</div><h1>MIDTERM<br>SIGNALS</h1><p class="hero-deck">A public, probabilistic election reference: current forecast, every federal legislative race, polling, scenarios, history and the provenance behind the numbers.</p></div><div class="countdown-block"><strong>${MODEL.days_to_election}</strong><span>DAYS TO 3 NOVEMBER 2026</span></div></div><div class="meta-line"><span>Last forecast <b>${dateFmt(MODEL.generated_at)}</b></span><span>Model <b>${esc(MODEL.model)}</b></span><span>Last data refresh <b>${dateFmt(MODEL.data_refreshed_at||MODEL.generated_at)}</b></span><span>Inputs <b>${esc((MODEL.provenance?.upstream_commit||'').slice(0,10)||'unavailable')}</b></span></div></section>
  <section class="chamber-pair">${partyProbBlock(h,'HOUSE')}${partyProbBlock(s,'SENATE')}</section>
  <section class="section"><div class="section-head"><div><div class="eyebrow">CONGRESS</div><h2>Joint control</h2><p>The four possible chamber-control combinations from the same correlated simulations.</p></div><a href="/?view=forecast" data-route="forecast">Forecast centre →</a></div><div class="joint-grid"><div class="joint-cell"><strong>${pct(j.dem_house_dem_senate)}</strong><span>Democratic House + Democratic Senate</span></div><div class="joint-cell"><strong>${pct(j.dem_house_rep_senate)}</strong><span>Democratic House + Republican Senate</span></div><div class="joint-cell"><strong>${pct(j.rep_house_dem_senate)}</strong><span>Republican House + Democratic Senate</span></div><div class="joint-cell"><strong>${pct(j.rep_house_rep_senate)}</strong><span>Republican House + Republican Senate</span></div></div></section>
  <section class="section panel read-brief"><div><div class="eyebrow">THE 30-SECOND READ</div><h2>State of the race</h2></div><p>${esc(read)}</p></section>
  <section class="section split"><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">WHAT CHANGED?</div><h2>Since the previous forecast</h2></div><a href="/?view=history" data-route="history">History →</a></div>${renderChanges(changes)}</article><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">DATA HEALTH</div><h2>${current}/${source.length||'—'} sources current</h2></div><a href="/?view=data" data-route="data">Inspect →</a></div>${renderSourceMini(source)}</article></section>
  <section class="section split"><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">HOUSE</div><h2>Tipping-point races</h2></div><a href="/?view=house" data-route="house">House centre →</a></div><div class="race-list">${(MODEL.tipping_point_house||[]).slice(0,8).map(raceMini).join('')}</div></article><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">SENATE</div><h2>Control battlegrounds</h2></div><a href="/?view=senate" data-route="senate">Senate centre →</a></div><div class="race-list">${(MODEL.senate_battlegrounds||[]).slice(0,8).map(raceMini).join('')}</div></article></section>
  <section class="section split"><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">BIGGEST MOVERS</div><h2>Probability movement</h2></div><a href="/?view=races" data-route="races">Race Explorer →</a></div>${movers.some(r=>Math.abs(r.change?.dem_probability||0)>.0001)?movers.map(raceMini).join(''):empty('No material race-probability movement is recorded against the immediately previous snapshot.')}</article><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">MOST UNCERTAIN</div><h2>Closest races</h2></div><a href="/?view=map" data-route="map">Race grid →</a></div>${uncertain.map(raceMini).join('')}</article></section>
  <section class="section split"><article class="panel"><div class="section-head panel-pad"><div><div class="eyebrow">HOUSE CONTROL DISTRIBUTION</div><h2>Not a point prediction</h2></div></div>${distributionChart(h,435,'House')}</article><article class="panel"><div class="section-head panel-pad"><div><div class="eyebrow">SENATE CONTROL DISTRIBUTION</div><h2>Paths remain broad</h2></div></div>${distributionChart(s,100,'Senate')}</article></section>
  <section class="section thirds"><article class="panel panel-pad"><div class="eyebrow">NEW POLLS</div><h2>${MODEL.national_environment?.polls_in_35_day_window??'—'} in national window</h2><p class="muted">Generic-ballot polls are visible beside the MIDTERM SIGNALS aggregate; race polls live on individual race pages.</p><a href="/?view=polls" data-route="polls">Open polling centre →</a></article><article class="panel panel-pad"><div class="eyebrow">FORECASTER DISAGREEMENT</div><h2>${MODEL.external_forecasters?.configured_count?`${MODEL.external_forecasters.configured_count} feeds configured`:'External feeds not configured'}</h2><p class="muted">No proprietary rating is inferred or fabricated. Adapter boundaries are visible in Data & provenance.</p><a href="/?view=forecast" data-route="forecast">Comparison status →</a></article><article class="panel panel-pad"><div class="eyebrow">CAMPAIGN SIGNALS</div><h2>${MODEL.campaign_signals?.length||0} structured signals</h2><p class="muted">Qualitative signals are explicitly separated from numerical probabilities unless a documented quantitative adapter consumes them.</p><a href="/?view=signals" data-route="signals">Open signals →</a></article></section>`;
}
function renderChanges(changes){
  const items=[];
  if(Number.isFinite(changes.house_control_probability))items.push(['House control',deltaText(changes.house_control_probability),'Democratic probability']);
  if(Number.isFinite(changes.senate_control_probability))items.push(['Senate control',deltaText(changes.senate_control_probability),'Democratic probability']);
  if(Number.isFinite(changes.generic_ballot_d_minus_r))items.push(['Generic ballot',`${changes.generic_ballot_d_minus_r>=0?'+':''}${changes.generic_ballot_d_minus_r.toFixed(1)} pt`,'D−R aggregate']);
  for(const x of changes.changed_inputs||[])items.push(['Input changed',x,'Observed source file']);
  if(!items.length)return empty('No prior comparable v1 snapshot is available yet. No change has been invented.');
  return `<div class="change-list">${items.slice(0,7).map(([a,b,c])=>`<div class="change-item"><strong>${esc(a)}</strong><div><b>${esc(b)}</b><br><small>${esc(c)}</small></div><span></span></div>`).join('')}</div>`
}
function renderSourceMini(source){if(!source.length)return empty('Source-health report is not present in this snapshot.');return `<div class="source-list">${source.slice(0,6).map(s=>`<div class="source-item"><strong>${esc(s.label||s.id)}</strong><div><small>${esc(s.note||s.kind||'')}</small></div>${sourceState(s)}</div>`).join('')}</div>`}

function renderForecast(){
  const h=MODEL.summary.house,s=MODEL.summary.senate,j=MODEL.summary.joint_control||{};
  const now=MODEL.nowcast||MODEL.summary,eday=MODEL.election_day_forecast||MODEL.summary;
  $('#content').innerHTML=`${pageHead('FORECAST CENTRE','Forecast, uncertainty, paths','The official baseline and its uncertainty are numerical model outputs. The nowcast describes today’s measured environment; the election-day view preserves uncertainty about the final outcome.',metaRow('Model',MODEL.model)+metaRow('Simulations',(h.simulations||'—').toLocaleString?.()||h.simulations)+metaRow('Updated',dateFmt(MODEL.generated_at)))}
  <section class="chamber-pair">${partyProbBlock(h,'HOUSE')}${partyProbBlock(s,'SENATE')}</section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">NOWCAST</div><h2>If today’s measured environment held</h2><p>${esc(MODEL.forecast_notes?.nowcast||'The current model has no separate time-evolution layer; this view therefore uses the same measured environment as the official baseline and is labelled accordingly rather than implying extra precision.')}</p><div class="metric-line"><div class="metric"><b>${pct(now.house?.dem_control_probability??h.dem_control_probability)}</b><small>House D control</small></div><div class="metric"><b>${pct(now.senate?.dem_control_probability??s.dem_control_probability)}</b><small>Senate D control</small></div></div></article><article class="panel panel-pad"><div class="eyebrow">ELECTION-DAY FORECAST</div><h2>3 November 2026</h2><p>${esc(MODEL.forecast_notes?.election_day||'The production baseline represents election-outcome uncertainty under the current model specification. Future political movement is not separately modelled as a deterministic trend.')}</p><div class="metric-line"><div class="metric"><b>${pct(eday.house?.dem_control_probability??h.dem_control_probability)}</b><small>House D control</small></div><div class="metric"><b>${pct(eday.senate?.dem_control_probability??s.dem_control_probability)}</b><small>Senate D control</small></div></div></article></section>
  <section class="section panel panel-pad"><div class="eyebrow">MODEL CONFIDENCE ≠ POLITICAL CERTAINTY</div><h2>Probability describes repeated uncertainty, not vote share.</h2><p class="prose">An 80% probability does not mean an 80% vote share. It means that, under the assumptions represented by the model, outcomes of that class occur about four times in five across simulated election worlds. A 20% outcome is not a contradiction; it is an outcome the model explicitly said could happen.</p></section>
  <section class="section split"><article class="panel"><div class="panel-pad"><div class="eyebrow">HOUSE SEATS</div><h2>Full probability distribution</h2></div>${distributionChart(h,435,'House')}</article><article class="panel"><div class="panel-pad"><div class="eyebrow">SENATE SEATS</div><h2>Full probability distribution</h2></div>${distributionChart(s,100,'Senate')}</article></section>
  <section class="section"><div class="section-head"><div><div class="eyebrow">CONGRESS</div><h2>Control combinations</h2></div></div><div class="joint-grid"><div class="joint-cell"><strong>${pct(j.dem_house_dem_senate)}</strong><span>D House + D Senate</span></div><div class="joint-cell"><strong>${pct(j.dem_house_rep_senate)}</strong><span>D House + R Senate</span></div><div class="joint-cell"><strong>${pct(j.rep_house_dem_senate)}</strong><span>R House + D Senate</span></div><div class="joint-cell"><strong>${pct(j.rep_house_rep_senate)}</strong><span>R House + R Senate</span></div></div></section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">UNCERTAINTY</div><h2>Intervals</h2><div class="facts-grid"><div class="fact"><b>${intervalText(h,50)}</b><span>House 50%</span></div><div class="fact"><b>${intervalText(h,95)}</b><span>House 95%</span></div><div class="fact"><b>${intervalText(s,50)}</b><span>Senate 50%</span></div><div class="fact"><b>${intervalText(s,95)}</b><span>Senate 95%</span></div></div></article><article class="panel panel-pad"><div class="eyebrow">FORECASTER COMPARISON</div><h2>Native scales preserved</h2>${renderForecasterStatus()}</article></section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">TIPPING POINT</div><h2>${esc(MODEL.tipping_point_house?.[0]?.race_code||'Unavailable')}</h2>${MODEL.tipping_point_house?.slice(0,6).map(raceMini).join('')||empty('No tipping-point calculation available.')}</article><article class="panel panel-pad"><div class="eyebrow">SCENARIO LAB</div><h2>Stress the baseline</h2><p class="muted">Apply transparent national or chamber swings without overwriting the official forecast.</p><a href="/?view=scenarios" data-route="scenarios">Open Scenario Lab →</a></article></section>`;
}
function renderForecasterStatus(){const list=MODEL.external_forecasters?.sources||[{name:'Cook Political Report',state:'unavailable'},{name:'Inside Elections',state:'unavailable'},{name:"Sabato's Crystal Ball",state:'unavailable'},{name:'Silver Bulletin',state:'unavailable'},{name:'Decision Desk HQ',state:'unavailable'}];return `<div class="source-list">${list.map(s=>`<div class="source-item"><strong>${esc(s.name)}</strong><div><small>${esc(s.note||'No licensed automated feed configured.')}</small></div>${sourceState(s)}</div>`).join('')}</div>`}

function renderChamber(type){
  const isH=type==='house', ch=MODEL.summary[type], races=MODEL.races.filter(r=>r.race_type===type), competitive=races.filter(r=>r.dem_probability>=.3&&r.dem_probability<=.7), flips=races.filter(r=>(r.seat_holder==='REP'&&r.dem_probability>.5)||(r.seat_holder==='DEM'&&r.dem_probability<.5));
  const title=isH?'House Centre':'Senate Centre'; const deck=isH?'All 435 districts, the national seat distribution and the battlefield ordered by uncertainty.':'The 2026 Senate battlefield, seats not up this cycle, paths to 51 Democratic seats and candidate-specific contests.';
  $('#content').innerHTML=`${pageHead(type.toUpperCase(),title,deck,metaRow('Expected D seats',fmt(ch.expected_dem_seats,1))+metaRow('Control probability',pct(ch.dem_control_probability))+metaRow('80% interval',intervalText(ch,80)))}
  <section class="chamber-pair"><article class="chamber-card">${partyProbBlock(ch,isH?'HOUSE':'SENATE')}</article><article class="panel">${distributionChart(ch,isH?435:100,isH?'House':'Senate')}</article></section>
  ${!isH?renderSenatePaths(races,ch):''}
  <section class="section thirds"><article class="panel panel-pad"><div class="eyebrow">COMPETITIVE</div><h2>${competitive.length}</h2><p class="muted">Races between 30% and 70% Democratic win probability.</p></article><article class="panel panel-pad"><div class="eyebrow">MODEL-FAVOURED FLIPS</div><h2>${flips.length}</h2><p class="muted">Seats where the current model favourite differs from the recorded seat holder.</p></article><article class="panel panel-pad"><div class="eyebrow">TIPPING POINT</div><h2>${esc((isH?MODEL.tipping_point_house:MODEL.senate_battlegrounds)?.[0]?.race_code||'—')}</h2><p class="muted">Closest control-relevant race in the current ordering.</p></article></section>
  <section class="section"><div class="section-head"><div><div class="eyebrow">BATTLEFIELD</div><h2>${isH?'Accessible race grid':'State race grid'}</h2><p>Colour is secondary: every tile carries race text, probability and a D/R edge symbol.</p></div><a href="/?view=map" data-route="map">Full map/grid →</a></div>${renderRaceGrid(races.filter(r=>r.dem_probability>.08&&r.dem_probability<.92).sort((a,b)=>Math.abs(a.dem_probability-.5)-Math.abs(b.dem_probability-.5)).slice(0,isH?90:40))}</section>
  <section class="section"><div class="section-head"><div><div class="eyebrow">RACE TABLE</div><h2>${isH?'Every district':'Every Senate contest'}</h2></div><a href="/?view=races" data-route="races">Advanced Race Explorer →</a></div>${renderRaceTable(races.sort((a,b)=>Math.abs(a.dem_probability-.5)-Math.abs(b.dem_probability-.5)))}</section>`;
}
function renderSenatePaths(races,ch){const battles=races.filter(r=>r.dem_probability>.15&&r.dem_probability<.85).sort((a,b)=>b.dem_probability-a.dem_probability);const fixed=ch.fixed_not_up_dem_seats??34;const needed=Math.max(0,51-fixed);return `<section class="section panel panel-pad"><div class="section-head"><div><div class="eyebrow">HOW EACH PARTY GETS TO CONTROL</div><h2>Paths to 51 Democratic seats</h2><p>Democrats begin the simulated cycle with ${fixed} seats not up. They need ${needed} wins from the contests represented in the model to reach 51. This is not a claim that all paths are equally likely.</p></div></div><div class="race-list">${battles.slice(0,12).map(raceMini).join('')}</div></section>`}
function renderRaceGrid(rows){return `<div class="race-grid">${rows.map(r=>{const p=r.dem_probability,side=p>=.5?'D':'R',cls=p>=.45&&p<=.55?'toss':side==='D'?'d-edge':'r-edge';return `<button class="race-tile ${cls}" type="button" data-open-race="${esc(r.race_code)}" aria-label="${esc(r.race_code)}, ${side} edge, ${pct(Math.max(p,1-p))}"><span class="symbol">${esc(r.race_code)} · ${side}</span><small>${pct(Math.max(p,1-p))}<br>${esc(r.rating||'')}</small></button>`}).join('')}</div>`}
function raceRow(r){const side=winSide(r),fresh=r.latest_race_poll?(ageDays(`${r.latest_race_poll}T12:00:00Z`)<=21?'CURRENT':'STALE'):'UNAVAILABLE';return `<div class="race-row" role="button" tabindex="0" data-open-race="${esc(r.race_code)}" aria-label="Open ${esc(r.race_code)}"><div class="race-code">${esc(r.race_code)}</div><div class="candidate-cell"><span class="tag d">D</span>${esc(r.dem_candidate||'—')}<small class="mobile-opponent muted"> vs ${esc(r.rep_candidate||'—')}</small></div><div class="candidate-cell"><span class="tag r">R</span>${esc(r.rep_candidate||'—')}</div><div class="${side==='D'?'lead-d':'lead-r'}"><b>${pct(winProbability(r))}</b><br><small>${side} win</small></div><div>${signed(r.forecast_margin_d_minus_r)}</div><div>${esc(r.rating||'—')}</div><div>${r.poll_count||0}</div><div><span class="fresh ${fresh.toLowerCase()}">${fresh}</span></div></div>`}
function renderRaceTable(rows){return `<div class="race-table"><div class="race-row header"><div>RACE</div><div>DEMOCRAT / ALIGNED</div><div>REPUBLICAN</div><div>WIN PROB.</div><div>MARGIN</div><div>MODEL RATING</div><div>POLLS</div><div>FRESHNESS</div></div>${rows.map(raceRow).join('')}</div>`}

function renderRaces(){
  const p=new URLSearchParams(location.search); const filters={query:p.get('q')||'',chamber:p.get('chamber')||'all',state:p.get('state')||'all',party:p.get('party')||'all',competitiveness:p.get('competitive')||'all',polling:p.get('polling')||'all',minProb:Number(p.get('min')||0),maxProb:Number(p.get('max')||1)};
  const states=[...new Set(MODEL.races.map(r=>r.state))].sort(); let rows=filterRaces(MODEL.races,filters).sort((a,b)=>Math.abs(a.dem_probability-.5)-Math.abs(b.dem_probability-.5));
  $('#content').innerHTML=`${pageHead('RACE EXPLORER','Interrogate the battlefield','Filter House and Senate contests by geography, model probability, incumbent party, polling availability and competitiveness. Filter state is encoded in the URL for sharing.')}
  <div class="toolbar" id="raceToolbar"><input id="raceQ" type="search" value="${esc(filters.query)}" placeholder="Search race or candidate"><select id="raceChamber"><option value="all">House + Senate</option><option value="house">House</option><option value="senate">Senate</option></select><select id="raceState"><option value="all">All states</option>${states.map(s=>`<option value="${s}">${stateName(s)}</option>`).join('')}</select><select id="raceComp"><option value="all">All competitiveness</option><option value="tossup">Toss-ups 45–55</option><option value="competitive">Competitive 30–70</option><option value="uncertain">Most uncertain 40–60</option></select><button id="raceMore" type="button">More filters</button></div>
  <div class="toolbar hidden" id="moreFilters"><select id="raceParty"><option value="all">Any seat holder</option><option value="dem-held">Democratic-held</option><option value="rep-held">Republican-held</option><option value="dem-flip">R-held, D favoured</option><option value="rep-flip">D-held, R favoured</option></select><select id="racePolling"><option value="all">Any polling</option><option value="recent">Has race poll</option><option value="none">No recent race poll</option></select><label>Min D probability <input id="minProb" type="number" min="0" max="100" step="5" value="${filters.minProb*100}"></label><label>Max D probability <input id="maxProb" type="number" min="0" max="100" step="5" value="${filters.maxProb*100}"></label><button id="raceReset" type="button">Reset</button></div>
  <div class="filter-summary" id="filterSummary">${rows.length} of ${MODEL.races.length} races shown.</div><div id="raceResults">${renderRaceTable(rows)}</div>`;
  $('#raceChamber').value=filters.chamber;$('#raceState').value=filters.state;$('#raceComp').value=filters.competitiveness;
  const update=()=>{const f={query:$('#raceQ').value,chamber:$('#raceChamber').value,state:$('#raceState').value,party:$('#raceParty')?.value||'all',competitiveness:$('#raceComp').value,polling:$('#racePolling')?.value||'all',minProb:Number($('#minProb')?.value||0)/100,maxProb:Number($('#maxProb')?.value||100)/100};const r=filterRaces(MODEL.races,f).sort((a,b)=>Math.abs(a.dem_probability-.5)-Math.abs(b.dem_probability-.5));$('#raceResults').innerHTML=renderRaceTable(r);$('#filterSummary').textContent=`${r.length} of ${MODEL.races.length} races shown.`;const q=new URLSearchParams({view:'races'});for(const [k,v] of [['q',f.query],['chamber',f.chamber],['state',f.state],['party',f.party],['competitive',f.competitiveness],['polling',f.polling]])if(v&&v!=='all')q.set(k,v);if(f.minProb>0)q.set('min',f.minProb);if(f.maxProb<1)q.set('max',f.maxProb);history.replaceState(null,'',`/?${q}`)};
  $$('#raceToolbar input,#raceToolbar select,#moreFilters input,#moreFilters select').forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',update));$('#raceMore').addEventListener('click',()=>$('#moreFilters').classList.toggle('hidden'));$('#raceReset').addEventListener('click',()=>navigate({view:'races'}));
}

function renderMap(){const p=new URLSearchParams(location.search);const chamber=p.get('chamber')||'house',layer=p.get('layer')||'probability';const rows=MODEL.races.filter(r=>r.race_type===chamber).sort((a,b)=>a.state.localeCompare(b.state)||String(a.district||'').localeCompare(String(b.district||''),undefined,{numeric:true}));$('#content').innerHTML=`${pageHead('MAP / RACE GRID','The national battlefield','A colour-redundant race grid is used as the primary national map where redistributable congressional geometry is not configured. Every cell remains readable by text, keyboard and touch.')}
  <div class="toolbar"><select id="mapChamber"><option value="house">House</option><option value="senate">Senate</option></select><select id="mapLayer"><option value="probability">Model probability</option><option value="margin">Expected margin</option><option value="movement">Change since previous</option><option value="rating">Model rating</option></select><div></div><div></div><button id="mapCompetitive">Competitive only</button></div><div class="panel panel-pad"><p class="data-note"><b>Encoding:</b> D/R letters and numeric values carry the same information as the edge rail. Red/blue colour is never the sole signal.</p><div id="mapGrid">${renderRaceGrid(rows)}</div></div>`;$('#mapChamber').value=chamber;$('#mapLayer').value=layer;$('#mapChamber').addEventListener('change',e=>{const q=new URLSearchParams({view:'map',chamber:e.target.value,layer:$('#mapLayer').value});history.replaceState(null,'',`/?${q}`);renderMap()});$('#mapLayer').addEventListener('change',e=>{const q=new URLSearchParams({view:'map',chamber:$('#mapChamber').value,layer:e.target.value});history.replaceState(null,'',`/?${q}`)});$('#mapCompetitive').addEventListener('click',()=>{$('#mapGrid').innerHTML=renderRaceGrid(rows.filter(r=>r.dem_probability>=.2&&r.dem_probability<=.8))})}

function renderPolls(){const nat=MODEL.national_environment||{},polls=MODEL.polls||nat.recent_polls||[];const racePolls=(MODEL.races||[]).reduce((n,r)=>n+(r.poll_count||0),0);$('#content').innerHTML=`${pageHead('POLLING CENTRE','Polls are observations, not forecasts','Raw poll observations sit beside the MIDTERM SIGNALS aggregates. Issue polling is not mixed into electoral averages.',metaRow('Generic ballot',signed(nat.generic_ballot_d_minus_r))+metaRow('National window',`${nat.polls_in_35_day_window??'—'} polls`)+metaRow('Race-poll records',String(racePolls)))}
  <section class="chamber-pair"><article class="chamber-card"><div class="eyebrow">GENERIC CONGRESSIONAL BALLOT</div><h2>${signed(nat.generic_ballot_d_minus_r)}</h2><p class="muted">35-day weighted aggregate. Weighting accounts for recency, sample size, the source quality field present in the upstream dataset and partisan sponsorship. It is not a simple arithmetic average.</p></article><article class="chamber-card"><div class="eyebrow">PRESIDENTIAL APPROVAL</div><h2>${nat.presidential_approval?.net!=null?signed(nat.presidential_approval.net):'Unavailable'}</h2><p class="muted">${nat.presidential_approval?.net!=null?'Descriptive unless the documented model specification explicitly consumes it.':'No validated current presidential-approval adapter is present in the production input bundle. Missing is not zero.'}</p></article></section>
  <section class="section panel panel-pad"><div class="section-head"><div><div class="eyebrow">RAW NATIONAL POLLS</div><h2>Underlying generic-ballot observations</h2></div></div>${renderPollRows(polls)}</section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">HOUSE POLLS</div><h2>Race pages preserve underlying observations</h2><p class="muted">Use Race Explorer → polling availability to find races with current public race polling.</p><a href="/?view=races&chamber=house&polling=recent" data-route-url="/?view=races&chamber=house&polling=recent">Find polled House races →</a></article><article class="panel panel-pad"><div class="eyebrow">SENATE POLLS</div><h2>Candidate-specific where matched</h2><p class="muted">The production adapter rejects mismatched candidate matchups rather than silently treating them as current.</p><a href="/?view=races&chamber=senate&polling=recent" data-route-url="/?view=races&chamber=senate&polling=recent">Find polled Senate races →</a></article></section>`}
function renderPollRows(polls){if(!polls.length)return empty('No qualifying public polls are available in this snapshot. No average has been fabricated.');return `<div class="poll-list">${polls.map(p=>`<div class="poll-row"><div><strong>${esc(p.pollster||'Unknown pollster')}</strong><div class="poll-meta">${esc(p.sponsor||'')} ${p.sponsor_lean?`· partisan sponsor ${esc(p.sponsor_lean)}`:''}</div></div><div><small>${esc(p.start_date||'')} ${p.start_date?'–':''} ${esc(p.end_date||'')}</small></div><div><small>n=${p.n||'—'} · ${esc(p.population||p.sample_type||'sample n/a')}</small></div><div><small>D ${p.dem??'—'} / R ${p.rep??'—'}</small></div><div class="poll-margin ${Number(p.margin)>=0?'lead-d':'lead-r'}">${signed(Number(p.margin))}</div></div>`).join('')}</div>`}

function findRace(id){return MODEL.races.find(r=>r.race_code.toLowerCase()===String(id||'').toLowerCase())}
function renderRace(id){const r=findRace(id);if(!r){$('#content').innerHTML=`${pageHead('RACE','Race not found','The requested race code is not present in the current production universe.')} ${empty('Check the race code or use global search.')}`;return}const side=winSide(r),polls=r.polls||[],history=r.history||[],ext=r.external_forecasters||{};const st=stateName(r.state);document.title=`2026 ${r.race_type==='senate'?`${st} Senate`:`${r.race_code} House`} Election Forecast & Polls · MIDTERM SIGNALS`;$('#content').innerHTML=`
  <section class="race-hero"><div class="race-title"><div class="eyebrow">${r.race_type.toUpperCase()} · ${esc(st)}</div><h1>${esc(r.race_code)}</h1><div class="contest">2026 ${esc(r.race_type==='senate'?`${st} Senate election`:`${st} ${r.district}th congressional district`)}</div></div><div class="prob-block"><span>CURRENT MODEL FAVOURITE · ${side}</span><strong class="${side==='D'?'lead-d':'lead-r'}">${pct(winProbability(r))}</strong><small>${esc(r.rating)} · expected margin ${signed(r.forecast_margin_d_minus_r)}</small></div></section>
  <div class="candidate-matchup"><article class="candidate-card"><div class="eyebrow party-d">DEMOCRATIC / ALIGNED</div><h2>${esc(r.dem_candidate||'No qualifying nominee recorded')}</h2><p>${r.incumbent_party==='DEM'?'Incumbent party · ':''}${r.aligned_independent?'Democratic-aligned independent':''}</p><button class="link-button" data-open-candidate="${esc(r.dem_candidate||'')}">Candidate profile →</button></article><article class="candidate-card"><div class="eyebrow party-r">REPUBLICAN</div><h2>${esc(r.rep_candidate||'No qualifying nominee recorded')}</h2><p>${r.incumbent_party==='REP'?'Incumbent party':''}</p><button class="link-button" data-open-candidate="${esc(r.rep_candidate||'')}">Candidate profile →</button></article></div>
  <section class="section facts-grid"><div class="fact"><b>${pct(r.dem_probability)}</b><span>D win probability</span></div><div class="fact"><b>${signed(r.forecast_margin_d_minus_r)}</b><span>expected two-party margin</span></div><div class="fact"><b>${signed(r.relative_partisan_lean_d_minus_r)}</b><span>partisan baseline vs nation</span></div><div class="fact"><b>${r.poll_count||0}</b><span>qualifying recent race polls</span></div></section>
  <section class="section split"><article class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">FORECAST</div><h2>What the model says</h2></div></div><div class="metric-line"><div class="metric"><b>${pct(r.dem_probability)}</b><small>D win</small></div><div class="metric"><b>${pct(r.rep_probability)}</b><small>R win</small></div><div class="metric"><b>${fmt(r.dem_two_party_vote,1)}%</b><small>expected D 2-party</small></div><div class="metric"><b>${esc(r.rating)}</b><small>model category</small></div></div><p class="data-note">Probability is an uncertainty estimate, not a vote share. The categorical model rating is derived from MIDTERM SIGNALS probability bands.</p></article><article class="panel panel-pad"><div class="eyebrow">FUNDAMENTALS</div><h2>Prior context</h2><div class="facts-grid"><div class="fact"><b>${signed(r.presidential_margin_2024)}</b><span>2024 presidential margin</span></div><div class="fact"><b>${signed(r.prior_margin)}</b><span>pre-race-poll prior</span></div><div class="fact"><b>${esc(r.incumbent_party||'Open / other')}</b><span>incumbent party</span></div><div class="fact"><b>${r.latest_race_poll?dayFmt(r.latest_race_poll):'None'}</b><span>latest qualifying poll</span></div></div></article></section>
  <section class="section panel panel-pad"><div class="section-head"><div><div class="eyebrow">PROBABILITY HISTORY</div><h2>Forecast through time</h2></div><a href="/?view=history" data-route="history">Full archive →</a></div>${renderRaceHistory(history,r)}</section>
  <section class="section panel panel-pad"><div class="section-head"><div><div class="eyebrow">POLLING</div><h2>Underlying qualifying polls</h2><p>Analytical exclusions here do not modify the official forecast.</p></div></div>${polls.length?renderPollRows(polls):empty(`No qualifying public ${r.race_code} polls are recorded in the current MIDTERM SIGNALS race-poll window. Missing polling remains missing.`)}</section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">EXTERNAL FORECASTERS</div><h2>Native ratings, when licensed</h2>${renderRaceForecasters(ext)}</article><article class="panel panel-pad"><div class="eyebrow">CAMPAIGN MONEY</div><h2>FEC reporting</h2>${r.money?renderMoney(r.money):empty('No current FEC adapter output is attached to this race. Financial figures are not guessed or copied from mismatched reporting periods.')}</article></section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">CAMPAIGN SIGNALS</div><h2>Structured developments</h2>${renderSignals((MODEL.campaign_signals||[]).filter(x=>x.race_code===r.race_code))}</article><article class="panel panel-pad"><div class="eyebrow">SOURCES & PROVENANCE</div><h2>Where this came from</h2><p class="prose">Race metadata and polling are drawn from the production input mirror pinned at commit <code>${esc((MODEL.provenance?.upstream_commit||'').slice(0,12))}</code>. The numerical forecast is computed by MIDTERM SIGNALS using model <code>${esc(MODEL.model)}</code>.</p><a href="/?view=data" data-route="data">Inspect full provenance →</a></article></section>`}
function renderRaceHistory(history,r){if(!history.length)return empty('No multi-snapshot race history is embedded yet. The immutable forecast archive remains available and future v1 snapshots will populate this timeline without rewriting prior forecasts.');const pts=history.slice(-30);const maxW=100;return `<div class="timeline-list">${pts.map(x=>`<div class="timeline"><small>${dayFmt(x.date||x.generated_at)}</small><div class="track"><span style="width:${(x.dem_probability??.5)*maxW}%"></span></div><strong>${pct(x.dem_probability)}</strong></div>`).join('')}</div>`}
function renderRaceForecasters(ext){const names=['Cook Political Report','Inside Elections',"Sabato's Crystal Ball",'Silver Bulletin','Decision Desk HQ'];return `<div class="source-list">${names.map(name=>{const x=ext[name]||{};return `<div class="source-item"><strong>${esc(name)}</strong><div><small>${esc(x.rating||x.note||'No licensed current rating configured.')}</small></div>${sourceState({state:x.rating?'current':'unavailable'})}</div>`}).join('')}</div>`}
function renderMoney(m){return `<div class="facts-grid"><div class="fact"><b>${m.receipts!=null?`$${Number(m.receipts).toLocaleString()}`:'—'}</b><span>receipts</span></div><div class="fact"><b>${m.cash_on_hand!=null?`$${Number(m.cash_on_hand).toLocaleString()}`:'—'}</b><span>cash on hand</span></div><div class="fact"><b>${m.disbursements!=null?`$${Number(m.disbursements).toLocaleString()}`:'—'}</b><span>spending</span></div><div class="fact"><b>${esc(m.coverage_through||'—')}</b><span>reporting through</span></div></div>`}

function renderEnvironment(){const n=MODEL.national_environment||{};const fields=[['Generic ballot',signed(n.generic_ballot_d_minus_r),'Current weighted electoral input'],['Presidential approval',n.presidential_approval?.net!=null?signed(n.presidential_approval.net):'Unavailable','No zero-filling'],['Congressional approval',n.congressional_approval?.net!=null?signed(n.congressional_approval.net):'Unavailable','Descriptive only unless documented'],['Special elections',n.special_elections?.index??'Unavailable','No validated production adapter yet'],['Inflation',n.economy?.inflation??'Unavailable','Economic context'],['Labour market',n.economy?.labour_market??'Unavailable','Economic context'],['Consumer sentiment',n.economy?.consumer_sentiment??'Unavailable','Economic context']];$('#content').innerHTML=`${pageHead('NATIONAL ENVIRONMENT','The political weather, without determinism','National context is separated from race polling. Variables are displayed only when a validated adapter exists; absence is shown explicitly rather than converted to zero.')}
  <section class="thirds">${fields.map(([a,b,c])=>`<article class="panel panel-pad"><div class="eyebrow">${esc(a)}</div><h2>${esc(b)}</h2><p class="muted">${esc(c)}</p></article>`).join('')}</section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">GENERIC BALLOT</div><h2>${signed(n.generic_ballot_d_minus_r)}</h2><p class="prose">The current model uses a 35-day weighted generic congressional ballot aggregate. It is one input among district/state baselines, incumbency and qualifying race polling.</p>${renderPollRows((n.recent_polls||[]).slice(0,8))}</article><article class="panel panel-pad"><div class="eyebrow">HISTORICAL COMPARISON</div><h2>2010 · 2014 · 2018 · 2022</h2>${empty('Comparable same-point historical national-environment series are not yet reconstructed in a leakage-safe production dataset. The interface reserves this comparison without inventing values.')}</article></section>`}

function candidateRaces(name){return MODEL.races.filter(r=>r.dem_candidate===name||r.rep_candidate===name)}
function renderCandidates(){const map=new Map();for(const r of MODEL.races){for(const [party,name] of [['D',r.dem_candidate],['R',r.rep_candidate]])if(name&&!map.has(name))map.set(name,{name,party,race:r})}const list=[...map.values()].sort((a,b)=>Math.abs(a.race.dem_probability-.5)-Math.abs(b.race.dem_probability-.5));$('#content').innerHTML=`${pageHead('CANDIDATES','Candidates in the production race universe','Profiles contain only sourced fields carried by the election dataset or authoritative financial adapters. Missing biography is left missing.')}
  <div class="toolbar"><input id="candidateQ" type="search" placeholder="Search candidate or race"><select id="candidateParty"><option value="all">All parties</option><option value="D">Democratic / aligned</option><option value="R">Republican</option></select><div></div><div></div><div></div></div><div id="candidateList" class="race-table">${renderCandidateList(list)}</div>`;const run=()=>{const q=$('#candidateQ').value.toLowerCase(),party=$('#candidateParty').value;const rows=list.filter(x=>(party==='all'||x.party===party)&&(!q||`${x.name} ${x.race.race_code}`.toLowerCase().includes(q)));$('#candidateList').innerHTML=renderCandidateList(rows)};$('#candidateQ').addEventListener('input',run);$('#candidateParty').addEventListener('change',run)}
function renderCandidateList(list){return list.map(x=>`<div class="race-row" role="button" tabindex="0" data-open-candidate="${esc(x.name)}"><div class="race-code">${esc(x.race.race_code)}</div><div class="candidate-cell"><span class="tag ${x.party.toLowerCase()}">${x.party}</span>${esc(x.name)}</div><div>${esc(stateName(x.race.state))}</div><div>${x.party==='D'?pct(x.race.dem_probability):pct(x.race.rep_probability)}</div><div>${esc(x.race.rating)}</div><div>${x.race.poll_count||0} polls</div><div></div><div></div></div>`).join('')}
function renderCandidate(id){let name=id;const decoded=decodeURIComponent(String(id||''));let races=candidateRaces(decoded);if(!races.length){const candidateNames=[...new Set(MODEL.races.flatMap(r=>[r.dem_candidate,r.rep_candidate]).filter(Boolean))];name=candidateNames.find(n=>slugify(n)===slugify(decoded))||decoded;races=candidateRaces(name)}if(!races.length){$('#content').innerHTML=`${pageHead('CANDIDATE','Candidate not found','No candidate with that identifier is present in the current production race universe.')}`;return}const r=races[0],party=r.dem_candidate===name?'D':'R';$('#content').innerHTML=`${pageHead('CANDIDATE PROFILE',name,`Sourced election profile for ${raceLabel(r)}. No unsourced biography is generated.`,metaRow('Party / alignment',party)+metaRow('Race',r.race_code)+metaRow('Model win probability',pct(party==='D'?r.dem_probability:r.rep_probability)))}
  <section class="split"><article class="panel panel-pad"><div class="eyebrow">RACE</div><h2>${esc(r.race_code)}</h2><p>${esc(r.dem_candidate||'—')} vs ${esc(r.rep_candidate||'—')}</p><button class="button secondary" data-open-race="${esc(r.race_code)}">Open race page</button></article><article class="panel panel-pad"><div class="eyebrow">CAMPAIGN WEBSITE / BIOGRAPHY</div><h2>Source required</h2>${empty('No authoritative candidate biography or campaign-website field is present in the current production input schema. MIDTERM SIGNALS does not fill this gap from memory or generated prose.')}</article></section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">MONEY</div><h2>FEC committee data</h2>${r.money?renderMoney(r.money):empty('FEC adapter not configured for this candidate in the current production snapshot.')}</article><article class="panel panel-pad"><div class="eyebrow">RELATED POLLING</div><h2>${r.poll_count||0} qualifying race polls</h2>${(r.polls||[]).length?renderPollRows(r.polls.slice(0,6)):empty('No qualifying race polls are attached.')}</article></section>`}

function renderMoneyCentre(){const configured=MODEL.money?.state==='current';$('#content').innerHTML=`${pageHead('MONEY / FEC','Campaign money, with reporting periods intact','Financial data are shown only from authoritative FEC-compatible records and only with coverage dates. Mismatched reporting periods are not silently compared.')}
  <section class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">FEC ADAPTER</div><h2>${configured?'Current production feed':'Not configured'}</h2></div>${sourceState({state:configured?'current':'unavailable'})}</div>${configured?renderMoneyTable(MODEL.money.records||[]):empty('The v1 adapter boundary is implemented, but no current FEC API credential/feed is configured in the production pipeline. This does not block the election forecast.')}</section>
  <section class="section panel panel-pad"><div class="eyebrow">COMPARABILITY RULE</div><h2>Coverage dates travel with every dollar figure.</h2><p class="prose">MIDTERM SIGNALS will not compare receipts, spending or cash-on-hand figures from mismatched FEC reporting periods without an explicit warning. Outside spending will remain a separate series where available.</p></section>`}
function renderMoneyTable(rows){if(!rows.length)return empty('No financial records in the current production snapshot.');return `<div class="race-table">${rows.map(x=>`<div class="race-row"><div>${esc(x.race_code)}</div><div>${esc(x.candidate)}</div><div>$${Number(x.receipts||0).toLocaleString()}</div><div>$${Number(x.cash_on_hand||0).toLocaleString()}</div><div>${esc(x.coverage_through||'')}</div><div></div><div></div><div></div></div>`).join('')}</div>`}

function renderSignals(signals=MODEL.campaign_signals||[]){if(!signals.length)return empty('No structured campaign-signal records are present. Qualitative news is not being smuggled into the probability model.');return `<div class="signal-list">${signals.map(s=>`<div class="signal-item"><strong>${dayFmt(s.date)}</strong><div><b>${esc(s.category)}</b> · ${esc(s.geography||s.race_code||'National')}<br><small>${esc(s.description)}</small></div><span class="fresh ${s.model_effect&&s.model_effect!=='NONE'?'stale':'current'}">MODEL EFFECT: ${esc(s.model_effect||'NONE')}</span></div>`).join('')}</div>`}
function renderSignalsPage(){const all=MODEL.campaign_signals||[];$('#content').innerHTML=`${pageHead('CAMPAIGN SIGNALS','Election intelligence, structurally separated','A factual, filterable layer for polling, fundraising, candidate events, redistricting, legal changes and campaign resource signals. Default numerical model effect is NONE.')}
  <section class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">STRUCTURED SIGNALS</div><h2>${all.length} records</h2></div></div>${renderSignals(all)}</section>`}

function renderScenarios(){const p=new URLSearchParams(location.search),g=Number(p.get('gcb')||0),h=Number(p.get('houseSwing')||0),s=Number(p.get('senateSwing')||0);const base=MODEL.summary;const result=runScenario(MODEL,{genericBallotShift:g,houseSwing:h,senateSwing:s});$('#content').innerHTML=`${pageHead('SCENARIO LAB','Stress the baseline, never overwrite it','Transparent counterfactuals recompute chamber simulations from the published race margins. Every output is labelled SCENARIO, NOT OFFICIAL FORECAST.')}
  <div class="scenario-banner">SCENARIO, NOT OFFICIAL FORECAST · official baseline remains unchanged</div>
  <section class="section panel panel-pad"><div class="preset-row"><button data-scenario-g="1">POLLS D+1</button><button data-scenario-g="2">D+2</button><button data-scenario-g="3">D+3</button><button data-scenario-g="-1">R+1</button><button data-scenario-g="-2">R+2</button><button data-scenario-g="-3">R+3</button><button data-scenario-g="5">D+5</button><button data-scenario-g="-5">R+5</button></div><div class="scenario-controls"><div class="scenario-control"><label>Generic ballot shift, D−R points</label><input id="scG" type="number" min="-10" max="10" step="0.5" value="${g}"></div><div class="scenario-control"><label>House national swing, D−R points</label><input id="scH" type="number" min="-10" max="10" step="0.5" value="${h}"></div><div class="scenario-control"><label>Senate national swing, D−R points</label><input id="scS" type="number" min="-10" max="10" step="0.5" value="${s}"></div></div><div class="preset-row"><button class="button secondary" id="scenarioReset">RESET TO OFFICIAL FORECAST</button><button class="button" id="scenarioShare">COPY SHARE LINK</button></div></section>
  <section id="scenarioOutput" class="scenario-output">${scenarioOutput(result,base)}</section>
  <section class="section panel panel-pad"><div class="eyebrow">BUILD YOUR OWN ELECTION</div><h2>Assign battlegrounds manually</h2><p class="muted">For explicit race-by-race counterfactuals, use the election builder. It never writes to production data.</p><button class="button secondary" data-route="builder">Open election builder</button></section>`;const rerun=()=>{const params={genericBallotShift:Number($('#scG').value||0),houseSwing:Number($('#scH').value||0),senateSwing:Number($('#scS').value||0)};$('#scenarioOutput').innerHTML=scenarioOutput(runScenario(MODEL,params),base);const q=new URLSearchParams({view:'scenarios',gcb:params.genericBallotShift,houseSwing:params.houseSwing,senateSwing:params.senateSwing});history.replaceState(null,'',`/?${q}`)};$$('[data-scenario-g]').forEach(b=>b.addEventListener('click',()=>{$('#scG').value=b.dataset.scenarioG;rerun()}));$$('#scG,#scH,#scS').forEach(x=>x.addEventListener('input',rerun));$('#scenarioReset').addEventListener('click',()=>navigate({view:'scenarios'}));$('#scenarioShare').addEventListener('click',async()=>{await navigator.clipboard?.writeText(location.href);$('#scenarioShare').textContent='LINK COPIED'})}
function scenarioOutput(x,base){return `<section class="chamber-pair">${partyProbBlock({...x.house,net_change_dem:x.house.expected_dem_seats-base.house.expected_dem_seats},'HOUSE')}${partyProbBlock({...x.senate,net_change_dem:x.senate.expected_dem_seats-base.senate.expected_dem_seats},'SENATE')}</section><div class="joint-grid"><div class="joint-cell"><strong>${pct(x.joint_control.dem_house_dem_senate)}</strong><span>D House + D Senate</span></div><div class="joint-cell"><strong>${pct(x.joint_control.dem_house_rep_senate)}</strong><span>D House + R Senate</span></div><div class="joint-cell"><strong>${pct(x.joint_control.rep_house_dem_senate)}</strong><span>R House + D Senate</span></div><div class="joint-cell"><strong>${pct(x.joint_control.rep_house_rep_senate)}</strong><span>R House + R Senate</span></div></div><p class="scenario-delta">Scenario simulation: ${x.simulations.toLocaleString()} correlated draws. This browser-side exploration does not modify the official forecast.</p>`}

function renderBuilder(){const races=MODEL.races.filter(r=>r.dem_probability>.08&&r.dem_probability<.92).sort((a,b)=>Math.abs(a.dem_probability-.5)-Math.abs(b.dem_probability-.5));const assignments={};for(const r of MODEL.races){if(r.dem_probability>=.55)assignments[r.race_code]='D';else if(r.dem_probability<=.45)assignments[r.race_code]='R'};$('#content').innerHTML=`${pageHead('BUILD YOUR OWN ELECTION','Assign the battlegrounds','Explore combinations manually. This is not a model run and never changes the official forecast.')}
  <div class="scenario-banner">EXPLORATORY MAP · NOT OFFICIAL FORECAST</div><div class="preset-row"><button id="modelFav" class="button secondary">START FROM MODEL FAVOURITES</button><button id="tossOpen" class="button secondary">TOSS-UPS UNASSIGNED</button><button id="buildReset" class="button secondary">RESET</button><button id="buildShare" class="button">SHARE THIS MAP</button></div><div id="assignments" class="assignment-grid">${races.map(r=>assignmentTile(r,assignments)).join('')}</div><div id="scoreStrip" class="score-strip"></div>`;const refresh=()=>{const s=buildElectionSummary(assignments,MODEL.races,MODEL.summary);$('#scoreStrip').innerHTML=`<div><strong>${s.houseDem} D / ${s.houseRep} R</strong><small>House · ${s.houseUnassigned} open · control ${s.houseControl}</small></div><div><strong>${s.senateDem} D / ${s.senateRep} R</strong><small>Senate · ${s.senateUnassigned} open · control ${s.senateControl}</small></div><div><strong>${Object.keys(assignments).length}</strong><small>races assigned</small></div><div><strong>Exploratory</strong><small>official forecast unchanged</small></div>`;$$('.assignment').forEach(tile=>{const code=tile.dataset.code;$$('button',tile).forEach(b=>b.classList.toggle('selected',assignments[code]===b.dataset.choice))})};document.addEventListener('click',builderClick,{once:false});function builderClick(e){const b=e.target.closest('.assignment button');if(!b||!$('#assignments')?.contains(b))return;assignments[b.closest('.assignment').dataset.code]=b.dataset.choice;refresh()}$('#modelFav').addEventListener('click',()=>{for(const r of MODEL.races)assignments[r.race_code]=r.dem_probability>=.5?'D':'R';refresh()});$('#tossOpen').addEventListener('click',()=>{for(const r of MODEL.races){if(r.dem_probability>.45&&r.dem_probability<.55)delete assignments[r.race_code];else assignments[r.race_code]=r.dem_probability>=.5?'D':'R'}refresh()});$('#buildReset').addEventListener('click',()=>{for(const k of Object.keys(assignments))delete assignments[k];refresh()});$('#buildShare').addEventListener('click',async()=>{const encoded=btoa(JSON.stringify(assignments));const u=new URL(location.href);u.searchParams.set('view','builder');u.searchParams.set('map',encoded);await navigator.clipboard?.writeText(u.toString());$('#buildShare').textContent='LINK COPIED'});refresh()}
function assignmentTile(r,a){return `<div class="assignment" data-code="${esc(r.race_code)}"><strong>${esc(r.race_code)}</strong><small>${pct(r.dem_probability)} D baseline</small><div class="choice"><button class="d ${a[r.race_code]==='D'?'selected':''}" data-choice="D">D</button><button class="r ${a[r.race_code]==='R'?'selected':''}" data-choice="R">R</button></div></div>`}

async function loadHistorySnapshots(){if(MODEL.history_summaries?.length)return MODEL.history_summaries;if(!HISTORY_INDEX){try{HISTORY_INDEX=await fetch('/data/history/index.json',{cache:'no-store'}).then(r=>r.ok?r.json():Promise.reject(r.status))}catch{return []}}const files=(HISTORY_INDEX.snapshots||[]).slice(0,40);const out=[];for(const f of files){try{const s=await fetch(`/data/history/${f}`,{cache:'no-store'}).then(r=>r.json());out.push({file:f,generated_at:s.generated_at,house:s.summary?.house?.dem_control_probability,senate:s.summary?.senate?.dem_control_probability,gcb:s.national_environment?.generic_ballot_d_minus_r,house_seats:s.summary?.house?.expected_dem_seats,senate_seats:s.summary?.senate?.expected_dem_seats})}catch{}}return out}
async function renderHistory(){$('#content').innerHTML=`${pageHead('FORECAST HISTORY','Snapshots, not rewritten memory','Every production numerical refresh is preserved. Select a date to see what MIDTERM SIGNALS actually said then, not a reconstruction after the fact.')}<section class="panel panel-pad"><p class="muted">Loading immutable snapshots…</p></section>`;const rows=await loadHistorySnapshots();$('#content').innerHTML=`${pageHead('FORECAST HISTORY','Snapshots, not rewritten memory','Every production numerical refresh is preserved. Select a date to see what MIDTERM SIGNALS actually said then, not a reconstruction after the fact.')}
  <section class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">TIMELINE</div><h2>${rows.length} recent snapshots</h2></div></div>${rows.length?`<div class="history-list">${rows.map(x=>`<div class="history-row"><button data-history-file="${esc(x.file||'')}">${dateFmt(x.generated_at)}</button><div><small>House D control</small><br><strong>${pct(x.house)}</strong></div><div><small>Senate D control</small><br><strong>${pct(x.senate)}</strong></div><div><small>House D seats</small><br><strong>${fmt(x.house_seats,1)}</strong></div><div><small>Generic ballot</small><br><strong>${signed(x.gcb)}</strong></div></div>`).join('')}</div>`:empty('No archived production snapshots are indexed.')}</section>
  <section class="section panel panel-pad"><div class="eyebrow">WHAT CHANGED?</div><h2>Input-attributed movement</h2>${renderChanges(MODEL.change_summary||{})}</section>`}

function renderData(){const source=MODEL.source_health||SOURCES?.sources||[];$('#content').innerHTML=`${pageHead('DATA & PROVENANCE','Where every important number came from','Current, stale and unavailable are explicit states. Raw observations, model outputs, external forecasts, campaign signals and actual results remain separate data layers.',metaRow('Input SHA-256',(MODEL.provenance?.input_sha256||'').slice(0,16)||'—')+metaRow('Upstream commit',(MODEL.provenance?.upstream_commit||'').slice(0,12)||'—')+metaRow('Model',MODEL.model))}
  <section class="panel panel-pad"><div class="section-head"><div><div class="eyebrow">SOURCE HEALTH</div><h2>Production adapters</h2></div></div>${renderSources(source)}</section>
  <section class="section"><div class="section-head"><div><div class="eyebrow">DOWNLOADS</div><h2>Public machine-readable data</h2></div></div><div class="download-grid"><a class="download-card" href="/data/forecast.json"><strong>Forecast JSON</strong><span>Complete current production snapshot</span></a><a class="download-card" href="/data/races.csv"><strong>Race forecasts CSV</strong><span>Redistributable derived model outputs</span></a><a class="download-card" href="/data/polls.csv"><strong>Poll observations CSV</strong><span>Public upstream observations where redistribution permits</span></a><a class="download-card" href="/data/source-status.json"><strong>Source status JSON</strong><span>Current / stale / unavailable states</span></a><a class="download-card" href="/data/search.json"><strong>Search index JSON</strong><span>Race, candidate and pollster navigation index</span></a><a class="download-card" href="/data/history/index.json"><strong>Snapshot index</strong><span>Immutable forecast archive</span></a></div></section>
  <section class="section split"><article class="panel panel-pad"><div class="eyebrow">TRANSFORMATION</div><h2>Provenance chain</h2><div class="prose"><p><b>Source:</b> ${esc(MODEL.provenance?.upstream_input_mirror||'Unavailable')}</p><p><b>Retrieved / built:</b> ${dateFmt(MODEL.generated_at)}</p><p><b>Files:</b> ${(MODEL.provenance?.files||[]).map(esc).join(', ')||'Unavailable'}</p><p><b>Transformation:</b> ${esc(MODEL.provenance?.note||'See methodology.')}</p><p><b>Model version:</b> ${esc(MODEL.model)}</p></div></article><article class="panel panel-pad"><div class="eyebrow">LICENSING BOUNDARIES</div><h2>Unavailable beats improper</h2><p class="prose">MIDTERM SIGNALS does not bypass paywalls or invent licensed ratings. Proprietary forecasters remain explicit adapter boundaries until a permitted feed or manual import is configured. Copyrighted prose is not republished.</p></article></section>`}
function renderSources(source){if(!source.length)return empty('No source-status file is present in this snapshot.');return `<div class="source-list">${source.map(s=>`<div class="source-item"><strong>${esc(s.label||s.id)}</strong><div class="source-detail"><small>${esc(s.note||'')}${s.last_success?` · last success ${dateFmt(s.last_success)}`:''}</small>${s.url?`<br><a href="${esc(s.url)}" rel="noopener noreferrer">Source ↗</a>`:''}</div>${sourceState(s)}</div>`).join('')}</div>`}

function renderMethodology(){const m=MODEL.methodology||{};$('#content').innerHTML=`${pageHead('METHODOLOGY','A layered explanation','Read the 30-second overview, the five-minute architecture or the technical assumptions. The model is open to inspection and prospective changes are versioned.')}
  <div class="method-nav"><button class="active" data-method="short">30-second version</button><button data-method="medium">Five-minute version</button><button data-method="technical">Technical version</button><button data-method="health">Model health</button><button data-method="guide">Election guide</button></div><section id="methodBody" class="panel panel-pad prose">${methodShort(m)}</section>`;$$('[data-method]').forEach(b=>b.addEventListener('click',()=>{$$('[data-method]').forEach(x=>x.classList.toggle('active',x===b));const key=b.dataset.method;$('#methodBody').innerHTML=key==='short'?methodShort(m):key==='medium'?methodMedium(m):key==='technical'?methodTechnical(m):key==='health'?modelHealth():electionGuide()}))}
function methodShort(m){return `<h2>What the model broadly does</h2><p>MIDTERM SIGNALS starts with district or state partisan baselines, adds the measured national environment, incumbency and qualifying current race polling, then converts race margins into probabilities. Chamber control comes from correlated Monte Carlo simulations so many races can be wrong in the same direction.</p><div class="callout">News reporting, campaign rhetoric and LLM judgement do not silently alter numerical probabilities.</div>`}
function methodMedium(m){return `<h2>1. Build a structural prior</h2><p>${esc(m.partisan_lean||'Recent presidential results are blended and centred on the national vote to estimate district/state lean.')}</p><h2>2. Add national environment</h2><p>${esc(m.national_environment||'The generic ballot is aggregated with recency, sample-size and source-quality weighting.')}</p><h2>3. Use race polling carefully</h2><p>${esc(m.race_polling||'Qualifying candidate-matched polls are blended with the prior; missing polling remains missing.')}</p><h2>4. Simulate correlated error</h2><p>${esc(m.probabilities||'Race outcomes are simulated with both national and local error terms.')}</p><h2>5. Freeze provenance</h2><p>Each snapshot records an upstream commit, input hash, model version and timestamp. Historical snapshots are not rewritten after later information arrives.</p>`}
function methodTechnical(m){return `<h2>Technical architecture</h2><p><b>Partisan baseline:</b> ${esc(m.partisan_lean||'See source code.')}</p><p><b>National environment:</b> ${esc(m.national_environment||'See source code.')}</p><p><b>Incumbency:</b> ${esc(m.incumbency||'See source code.')}</p><p><b>Race polling:</b> ${esc(m.race_polling||'See source code.')}</p><p><b>Race probability:</b> ${esc(m.race_probability||'Normal-error conversion from forecast margin, with uncertainty reduced only by qualifying poll evidence within documented bounds.')}</p><p><b>Chamber simulation:</b> ${esc(m.probabilities||'Correlated Monte Carlo simulation.')}</p><p><b>Senate control:</b> ${esc(m.senate_control||'51 Democratic seats required under the current vice-presidential tie-break assumption.')}</p><div class="callout warning"><b>Prospective integrity:</b> model parameters are not retuned merely because the output looks surprising or differs from external forecasters.</div><p><a href="https://github.com/MusicOfScience/midterm-signals/blob/main/scripts/build_forecast.py">Read the production model source ↗</a></p>`}
function modelHealth(){return `<h2>Historical validation status</h2><div class="callout warning"><b>2018 and 2022 Brier score / log loss: unavailable.</b> The repository does not yet contain rigorous leakage-free historical replays for those cycles. MIDTERM SIGNALS will not manufacture backtest metrics from data that may include future information.</div><p>The v1.0 infrastructure reserves Brier score, log loss, calibration, seat-count error and interval coverage. These fields remain explicitly unavailable until retrospective reconstruction can pin historically available inputs and model versions at each replay date.</p><h2>Current production sanity checks</h2><p>The pipeline validates race universes, probability bounds, seat totals, dates, duplicate identifiers, provenance fields, source staleness and large unexplained forecast jumps before publication.</p>`}
function electionGuide(){const items=[['What is a midterm?','A federal election held halfway through a president’s four-year term.'],['Why every House seat?','US House members serve two-year terms, so all 435 voting seats are contested every two years.'],['Why only part of the Senate?','Senators serve six-year terms in staggered classes; roughly one-third face election every two years, plus any special elections.'],['Generic ballot','A national polling question asking which party a voter prefers for Congress, without naming local candidates.'],['Toss-up','A categorical shorthand for a race with no clear favourite. MIDTERM SIGNALS still shows the underlying probability.'],['70% probability','Not 70% of the vote: about seven wins in ten simulated worlds under the model assumptions.'],['Polling error','The difference between a poll estimate and the underlying electorate; some errors are shared across many races.'],['Tipping-point race','The race near the chamber-control threshold in the model’s ordering.'],['House effect','A systematic tendency for a pollster’s results to lean relative to the broader polling pool, estimated only when data support it.'],['Likely vs registered voter','Different poll populations: likely-voter screens estimate turnout; registered-voter polls include all registered respondents.'],['Why models disagree','Different priors, poll rules, uncertainty assumptions, data coverage and simulation structures can produce different forecasts.']];return `<h2>Election guide</h2><div class="glossary">${items.map(([a,b])=>`<article><h3>${esc(a)}</h3><p>${esc(b)}</p></article>`).join('')}</div>`}

function renderAbout(){$('#content').innerHTML=`${pageHead('ABOUT','What MIDTERM SIGNALS is for','A nonpartisan, open election-analysis system for the 2026 US midterms: fast enough for a casual visitor, inspectable enough for a researcher.')}
  <section class="split"><article class="panel panel-pad prose"><h2>Editorial contract</h2><p>Facts, polls, poll aggregates, model estimates, third-party forecasts, qualitative signals, scenarios and actual results are separate layers. Missing observations are never replaced with zero. Stale last-known-good values are marked stale. Qualitative text does not silently change numerical probabilities.</p></article><article class="panel panel-pad prose"><h2>Privacy</h2><p>The public application requires no account. It does not need personal information to explore races or scenarios. Any future analytics should remain privacy-respecting and compatible with Cloudflare’s minimal analytics model.</p></article></section>
  <section class="section panel panel-pad"><div class="eyebrow">ELECTION NIGHT / RESULTS MODE</div><h2>Architected, not faked.</h2><p class="prose">The results schema distinguishes <b>FORECAST</b>, <b>PROJECTED/CALLED</b> and <b>ACTUAL/OFFICIAL</b>. No live results are displayed until an authoritative or licensed results adapter is configured. The final pre-election forecast will be preserved permanently before results ingest begins.</p></section>`}

function renderPollster(id){const name=decodeURIComponent(String(id||''));const polls=(MODEL.polls||MODEL.national_environment?.recent_polls||[]).filter(p=>slugify(p.pollster)===slugify(name));const label=polls[0]?.pollster||name;$('#content').innerHTML=`${pageHead('POLLSTER',label,'Observable current-cycle records in MIDTERM SIGNALS. Historical performance metrics appear only when defensible leakage-safe data exist.',metaRow('Current records',String(polls.length))+metaRow('House effect','Unavailable')+metaRow('Historical grade','Not invented'))}<section class="panel panel-pad">${renderPollRows(polls)}</section><section class="section panel panel-pad"><div class="eyebrow">METHOD NOTE</div><h2>No borrowed pollster grade</h2><p class="prose">MIDTERM SIGNALS does not assign a grade merely because another organisation publishes one. Any future house-effect or performance estimate must be calculated from a documented dataset and methodology.</p></section>`}

function renderRoute(route){if(!MODEL)return;if(MODEL.__bootstrap&&['race','polls','pollster','candidate'].includes(route.view)){activeNav(route.view);$('#content').innerHTML='<div class="loading-screen"><div class="eyebrow">DEEP DATA</div><h1>Loading underlying observations</h1><p>Fetching the full immutable forecast snapshot for this detail view.</p></div>';if(!FULL_MODEL_PROMISE)FULL_MODEL_PROMISE=loadJSON('/data/forecast.json').then(full=>{if(full){MODEL=full;SEARCH=searchRecords(MODEL)}return full});FULL_MODEL_PROMISE.then(full=>{if(full)renderRoute(routeFromLocation());else $('#content').innerHTML='<div class="error-state"><h2>Detailed data unavailable</h2><p>The compact forecast remains available, but the full observation bundle could not be loaded.</p></div>'});return}activeNav(route.view);document.title='MIDTERM SIGNALS · 2026 US Midterm Forecast';switch(route.view){case'home':renderHome();break;case'forecast':renderForecast();break;case'house':renderChamber('house');break;case'senate':renderChamber('senate');break;case'races':renderRaces();break;case'map':renderMap();break;case'polls':renderPolls();break;case'environment':renderEnvironment();break;case'candidates':renderCandidates();break;case'candidate':renderCandidate(route.id);break;case'race':renderRace(route.id);break;case'pollster':renderPollster(route.id);break;case'money':renderMoneyCentre();break;case'signals':renderSignalsPage();break;case'scenarios':renderScenarios();break;case'builder':renderBuilder();break;case'history':renderHistory();break;case'data':renderData();break;case'methodology':renderMethodology();break;case'about':renderAbout();break;default:renderHome()}wireDynamic()}
function wireDynamic(){$$('[data-open-race]').forEach(x=>{const fn=()=>navigate({view:'race',id:x.dataset.openRace});x.addEventListener('click',fn);x.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fn()}})});$$('[data-open-candidate]').forEach(x=>x.addEventListener('click',()=>{if(x.dataset.openCandidate)navigate({view:'candidate',id:x.dataset.openCandidate})}));$$('[data-route-url]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();history.pushState(null,'',x.dataset.routeUrl);renderRoute(routeFromLocation())}));$$('[data-route="builder"]').forEach(x=>x.addEventListener('click',e=>{e.preventDefault();navigate({view:'builder'})}))}

function setupSearch(){const dialog=$('#searchDialog'),input=$('#globalSearch'),results=$('#searchResults');const open=()=>{dialog.showModal();setTimeout(()=>input.focus(),20)};$('#openSearch').addEventListener('click',open);document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();open()}if(e.key==='Escape'&&dialog.open)dialog.close()});input.addEventListener('input',()=>{const q=input.value;const hits=SEARCH.map(r=>[r,scoreSearch(r,q)]).filter(([,s])=>s>0).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([r])=>r);results.innerHTML=hits.length?hits.map((r,i)=>`<button type="button" class="search-result" role="option" data-search-type="${esc(r.type)}" data-search-key="${esc(r.key)}"><span class="type">${esc(r.type.toUpperCase())}</span><span><b>${esc(r.label)}</b><small>${esc(r.subtitle||'')}</small></span></button>`).join(''):`<p class="muted">No matching race, candidate, pollster or forecaster.</p>`;$$('.search-result',results).forEach(b=>b.addEventListener('click',()=>{dialog.close();const type=b.dataset.searchType,key=b.dataset.searchKey;if(type==='race')navigate({view:'race',id:key});else if(type==='candidate')navigate({view:'candidate',id:key});else if(type==='pollster')navigate({view:'pollster',id:key});else if(type==='forecaster')navigate({view:'forecast'})}))})}
function setupChrome(){const source=MODEL.source_health||SOURCES?.sources||[];const bad=source.filter(s=>['stale','unavailable','degraded','restricted'].includes(s.state||s.health));const chip=$('#healthChip');chip.classList.add(bad.length?'degraded':'current');chip.querySelector('span:last-child').textContent=bad.length?`${bad.length} source issue${bad.length===1?'':'s'}`:'Data current';chip.addEventListener('click',()=>navigate({view:'data'}));$('#contextBar').innerHTML=`<span><strong>${esc(MODEL.model)}</strong> · forecast ${dateFmt(MODEL.generated_at)} · generic ballot ${signed(MODEL.national_environment?.generic_ballot_d_minus_r)} · ${MODEL.races.length} federal legislative races modelled</span>`;$('#navToggle').addEventListener('click',()=>{const n=$('#primaryNav'),open=n.classList.toggle('open');$('#navToggle').setAttribute('aria-expanded',String(open))})}

async function loadJSON(url,fallback=null){try{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error(`${r.status}`);return await r.json()}catch(e){console.warn(url,e);return fallback}}
async function boot(){
  const initialRoute=routeFromLocation(),needsFull=['race','polls','pollster','candidate'].includes(initialRoute.view);[MODEL,STATUS,SOURCES]=await Promise.all([(needsFull?loadJSON('/data/forecast.json'):loadJSON('/data/bootstrap.json').then(x=>x||loadJSON('/data/forecast.json'))),loadJSON('/data/status.json',{}),loadJSON('/data/source-status.json',null)]);
  if(!MODEL){$('#content').innerHTML=`<div class="error-state"><h2>Forecast data unavailable</h2><p>The application shell loaded, but the production forecast snapshot could not be read. The last healthy deployment has not been replaced with fabricated numbers.</p></div>`;return}
  SEARCH=searchRecords(MODEL);for(const name of MODEL.pollster_names||[])if(!SEARCH.some(r=>r.type==='pollster'&&r.key===name))SEARCH.push({type:'pollster',label:name,subtitle:'Pollster',key:name,terms:name});setupChrome();setupSearch();renderRoute(routeFromLocation());
}
let __ENHANCEMENTS_PROMISE=null;
function __maybeLoadEnhancements(){
  const view=routeFromLocation().view;
  if(view==='home')return;
  if(!__ENHANCEMENTS_PROMISE)__ENHANCEMENTS_PROMISE=import('/enhancements.bundle.mjs').catch(err=>{console.warn('MIDTERM SIGNALS v1 enhancements unavailable',err);return null});
}
window.addEventListener('popstate',()=>setTimeout(__maybeLoadEnhancements,0));
document.addEventListener('click',()=>setTimeout(__maybeLoadEnhancements,0),{capture:true,passive:true});
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const nav=document.querySelector('#primaryNav'),toggle=document.querySelector('#navToggle');if(nav?.classList.contains('open')){nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false');toggle?.focus()}});
globalThis.__MIDTERM_READY__=boot().then(()=>{document.querySelector('.site-footer')?.removeAttribute('hidden');setTimeout(__maybeLoadEnhancements,0);return true}).catch(err=>{console.error(err);const main=document.querySelector('#content');if(main)main.innerHTML='<div class="error-state"><h2>Application failed to load</h2><p>The static shell is available, but the interactive application could not be initialised.</p></div>';throw err});
